// ChoO-choo train — voxel steam locomotive + tender + 2 passenger cars + track + station
// Wheels: spoked with red rims (not solid discs = not tank treads)
var CX=128, HW=7;
var LOCO_Z0=40, LOCO_Z1=95;
var TEN_Z0=95, TEN_Z1=125;
var CAR1_Z0=125, CAR1_Z1=162;
var CAR2_Z0=162, CAR2_Z1=199;
var TRACK_Z0=20, TRACK_Z1=230;
var RWY=1;
var WHEEL_R=10;
var WHEEL_X=10;
var WHY=RWY+WHEEL_R; // hub Y=11, bottom at Y=1 (on rail)

// Spoked wheel: red rim + gray spokes + center hub, in YZ plane at X=cx
function spokedWheel(cx,hub_y,cz,r){
  // Red rim
  for(var by=-r;by<=r;by++)
    for(var bz=-r;bz<=r;bz++){
      var d2=by*by+bz*bz;
      if(d2<=r*r+r && d2>=(r-1)*(r-1)-(r-1)) block(cx,hub_y+by,cz+bz,'red_wool');
    }
  // Gray spokes (8 spokes)
  for(var s=0;s<8;s++){
    var sa=s*Math.PI/4;
    for(var sr=2;sr<=r-2;sr++){
      var sy=Math.round(hub_y+sr*Math.sin(sa));
      var sz=Math.round(cz+sr*Math.cos(sa));
      block(cx,sy,sz,'gray_wool');
    }
  }
  // Center hub
  block(cx,hub_y-1,cz-1,'gray_wool');
  block(cx,hub_y-1,cz,'gray_wool');
  block(cx,hub_y-1,cz+1,'gray_wool');
  block(cx,hub_y,cz-1,'gray_wool');
  block(cx,hub_y,cz,'gold_block');
  block(cx,hub_y,cz+1,'gray_wool');
  block(cx,hub_y+1,cz-1,'gray_wool');
  block(cx,hub_y+1,cz,'gray_wool');
  block(cx,hub_y+1,cz+1,'gray_wool');
}

// === GROUND & TRACK ===
box(CX-15,0,TRACK_Z0,CX+15,0,TRACK_Z1,'grass_block');
box(CX-8,0,TRACK_Z0,CX+8,0,TRACK_Z1,'cobblestone');
for(var z=TRACK_Z0;z<TRACK_Z1;z+=2)
  box(CX-6,0,z,CX+6,0,z,'oak_planks');
for(var z=TRACK_Z0;z<TRACK_Z1;z++){
  block(CX-3,RWY,z,'iron_block');
  block(CX+3,RWY,z,'iron_block');
}

// === LOCOMOTIVE BODY ===
var BOILER_Y=WHY+WHEEL_R+2; // Y=23, above wheels
var BOILER_R=5;

// Smokebox at FRONT (low Z)
var SB_Z=LOCO_Z0+5;
for(var z=SB_Z;z<LOCO_Z0+18;z++){
  for(var a=0;a<360;a+=12){
    block(CX+Math.round(4*Math.cos(a*Math.PI/180)),BOILER_Y-1+Math.round(4*Math.sin(a*Math.PI/180)),z,'black_wool');
  }
}
for(var a=0;a<360;a+=12){
  block(CX+Math.round(4*Math.cos(a*Math.PI/180)),BOILER_Y-1+Math.round(4*Math.sin(a*Math.PI/180)),LOCO_Z0,'black_wool');
}

// Dome
block(CX,BOILER_Y+BOILER_R+1,LOCO_Z0+25,'gold_block');
block(CX,BOILER_Y+BOILER_R+2,LOCO_Z0+25,'gold_block');

// Firebox glow
block(CX,BOILER_Y+1,LOCO_Z1-18,'glowstone');
block(CX-1,BOILER_Y+1,LOCO_Z1-18,'black_wool');
block(CX+1,BOILER_Y+1,LOCO_Z1-18,'black_wool');
block(CX,BOILER_Y,LOCO_Z1-18,'black_wool');
block(CX,BOILER_Y+2,LOCO_Z1-18,'black_wool');

// Smokestack
for(var y=BOILER_Y+BOILER_R+1;y<=BOILER_Y+BOILER_R+12;y++){
  var sr=y<=BOILER_Y+BOILER_R+8?3:4;
  for(var a=0;a<360;a+=12)
    block(CX+Math.round(sr*Math.cos(a*Math.PI/180)),y,SB_Z+3,'stone');
}
for(var i=0;i<20;i++){
  var sy=BOILER_Y+BOILER_R+13+Math.floor(i*0.6);
  var sx=CX+Math.round(Math.sin(i*0.7)*(2+i*0.08));
  var sz=SB_Z+3+Math.round(Math.cos(i*0.5)*(1+i*0.04));
  block(sx,sy,sz,'black_wool');
}

// Cab at REAR
var CAB_Z=LOCO_Z1-5;
box(CX-HW,1,CAB_Z-5,CX+HW,1,CAB_Z+20,'red_wool');
box(CX-HW,3,CAB_Z-5,CX+HW,14,CAB_Z+15,'oak_planks');
box(CX-HW,3,CAB_Z-5,CX-HW,14,CAB_Z+15,'oak_planks');
box(CX+HW,3,CAB_Z-5,CX+HW,14,CAB_Z+15,'oak_planks');
box(CX-HW,3,CAB_Z+15,CX+HW,3,CAB_Z+15,'oak_planks');
box(CX-HW,15,CAB_Z-5,CX+HW,15,CAB_Z+15,'oak_planks');
for(var z=CAB_Z;z<CAB_Z+14;z+=4){
  box(CX-HW+1,6,z,CX-HW+1,10,z,'glass');
  box(CX+HW-1,6,z,CX+HW-1,10,z,'glass');
}
box(CX-2,6,CAB_Z+15,CX+2,10,CAB_Z+15,'glass');

// === TENDER ===
box(CX-HW,1,TEN_Z0,CX+HW,2,TEN_Z1,'red_wool');
box(CX-HW,3,TEN_Z0,CX+HW,8,TEN_Z1,'oak_log');
box(CX-HW,3,TEN_Z0,CX+HW,3,TEN_Z1,'oak_planks');
for(var z=TEN_Z0+2;z<TEN_Z1-2;z++)
  for(var x=CX-HW+2;x<CX+HW-2;x++){
    var ch=2+Math.floor(Math.sin((x-CX)*0.4)*1.2+Math.cos((z-TEN_Z0)*0.4)*1.2);
    if(ch<1) ch=1;
    for(var cy=4;cy<=3+ch;cy++) block(x,cy,z,'brown_wool');
  }

// === PASSENGER CARS ===
box(CX-HW+1,1,CAR1_Z0,CX+HW-1,1,CAR1_Z1,'red_wool');
box(CX-HW+1,BOILER_Y-5,CAR1_Z0,CX+HW-1,BOILER_Y+3,CAR1_Z1,'red_wool');
box(CX-HW,BOILER_Y-5,CAR1_Z0,CX+HW,BOILER_Y-5,CAR1_Z1,'white_wool');
for(var z=CAR1_Z0+4;z<CAR1_Z1;z+=5){
  box(CX-HW+1,BOILER_Y-3,CAR1_Z0+4,CX-HW+1,BOILER_Y+1,CAR1_Z0+7,'glass');
  box(CX+HW-1,BOILER_Y-3,CAR1_Z0+4,CX+HW-1,BOILER_Y+1,CAR1_Z0+7,'glass');
}
box(CX-HW,BOILER_Y-6,CAR1_Z0-1,CX+HW,BOILER_Y-6,CAR1_Z1+1,'stone_bricks');

box(CX-HW+1,1,CAR2_Z0,CX+HW-1,1,CAR2_Z1,'red_wool');
box(CX-HW+1,BOILER_Y-5,CAR2_Z0,CX+HW-1,BOILER_Y+3,CAR2_Z1,'blue_wool');
box(CX-HW,BOILER_Y-5,CAR2_Z0,CX+HW,BOILER_Y-5,CAR2_Z1,'white_wool');
for(var z=CAR2_Z0+4;z<CAR2_Z1;z+=5){
  box(CX-HW+1,BOILER_Y-3,CAR2_Z0+4,CX-HW+1,BOILER_Y+1,CAR2_Z0+7,'glass');
  box(CX+HW-1,BOILER_Y-3,CAR2_Z0+4,CX+HW-1,BOILER_Y+1,CAR2_Z0+7,'glass');
}
box(CX-HW,BOILER_Y-6,CAR2_Z0-1,CX+HW,BOILER_Y-6,CAR2_Z1+1,'stone_bricks');

// === WHEELS + RODS (DRAWN LAST) ===
var WHEEL_ZS=[50,58,66];

// Thick connecting rods — red, between wheel sets, visible at X±WHEEL_X
for(var z=50;z<=66;z++){
  block(CX-WHEEL_X,WHY-1,z,'red_wool');
  block(CX-WHEEL_X,WHY,z,'red_wool');
  block(CX-WHEEL_X,WHY+1,z,'red_wool');
  block(CX+WHEEL_X,WHY-1,z,'red_wool');
  block(CX+WHEEL_X,WHY,z,'red_wool');
  block(CX+WHEEL_X,WHY+1,z,'red_wool');
}

// Spoked driving wheels (red rim, gray spokes, gold hub)
for(var i=0;i<WHEEL_ZS.length;i++){
  spokedWheel(CX-WHEEL_X,WHY,WHEEL_ZS[i],WHEEL_R);
  spokedWheel(CX+WHEEL_X,WHY,WHEEL_ZS[i],WHEEL_R);
}

// Passenger car wheels
for(var z=CAR1_Z0+8;z<CAR1_Z1-5;z+=12){
  spokedWheel(CX-HW+2,WHY,z,7);
  spokedWheel(CX+HW-2,WHY,z,7);
}
for(var z=CAR2_Z0+8;z<CAR2_Z1-5;z+=12){
  spokedWheel(CX-HW+2,WHY,z,7);
  spokedWheel(CX+HW-2,WHY,z,7);
}

// === HEADLIGHT (DRAWN LAST so smokebox doesn't overwrite) ===
block(CX,BOILER_Y,LOCO_Z0-1,'glowstone');
block(CX,BOILER_Y+1,LOCO_Z0-1,'glowstone');

// === TREES ===
for(var z=30;z<220;z+=22){
  for(var ty=1;ty<=5;ty++) block(CX-22,ty,z,'oak_log');
  for(var dy=-2;dy<=2;dy++) for(var dx=-2;dx<=2;dx++)
    if(Math.abs(dx)+Math.abs(dy)<=3) block(CX-22+dx,5+dy,z,'oak_leaves');
  for(var ty=1;ty<=5;ty++) block(CX+22,ty,z,'oak_log');
  for(var dy=-2;dy<=2;dy++) for(var dx=-2;dx<=2;dx++)
    if(Math.abs(dx)+Math.abs(dy)<=3) block(CX+22+dx,5+dy,z,'oak_leaves');
}

// === STATION PLATFORM ===
box(CX+8,1,TRACK_Z1-25,CX+24,2,TRACK_Z1-5,'stone_bricks');
for(var z=TRACK_Z1-24;z<TRACK_Z1-6;z+=6)
  box(CX+8,3,z,CX+8,6,z,'oak_log');
box(CX+7,7,TRACK_Z1-25,CX+25,7,TRACK_Z1-4,'bricks');
block(CX+16,3,TRACK_Z1-15,'oak_log');
block(CX+16,4,TRACK_Z1-15,'glowstone');
block(CX+16,5,TRACK_Z1-15,'red_wool');
